import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'Test.'});
const session = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'run', timestamp: '2026-01-01T00:00:00.000Z'}],
});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

describe('Usage aggregation', () => {
  it('sums usage across multiple rounds', async () => {
    let receivedUsage: any;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        receivedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 'tool', description: 'd', inputSchema: {type: 'object'}}, async () => 'ok');

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [
          {type: 'tool_use', toolCall: {id: 'c1', name: 'tool', input: {}}},
          {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 10, outputTokens: 5, totalTokens: 15}},
        ],
        [
          {type: 'text', text: 'done'},
          {type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 20, outputTokens: 10, totalTokens: 30}},
        ],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(session());

    // Currently it only returns the last one: {inputTokens: 20, outputTokens: 10, totalTokens: 30}
    // We want the sum: {inputTokens: 30, outputTokens: 15, totalTokens: 45}
    expect(receivedUsage).toEqual({inputTokens: 30, outputTokens: 15, totalTokens: 45});
  });
});

